`src/components/admin/routing/__tests__/` only has `RoutingPolicyBar.test.ts`. `RoutingTable.tsx` (238 lines) has stateful per-row logic (`draft`/`dirty` tracking, pin vs. auto vs. recommendation states) and several formatting helpers (`fmtCost`, `fmtLatency`, `fmtEval`, `modelLabel`) that are module-private, so they're only reachable through rendering — no unit path around the DOM.

```typescript
// src/components/admin/routing/__tests__/RoutingTable.test.ts
import { describe, it, expect } from "bun:test";
import { render, fireEvent } from "@testing-library/react";
import React from "react";
import { RoutingTable } from "../RoutingTable";
import type { RoutingRow } from "@/lib/routing-console.functions";

const liveModels = [
  { id: "m1", label: "Model One", provider: "anthropic", tier: "flagship" },
];

function pinnedRow(over: Partial<RoutingRow> = {}): RoutingRow {
  return {
    surface: "chat",
    setting: { kind: "pinned", modelId: "m1" },
    autoModelId: "m1",
    costPerTaskUsd7d: 0.0123,
    latencyP50Ms7d: 850,
    evalScore: 92,
    callCount7d: 40,
    recommendation: null,
    recommendationReason: null,
    ...over,
  } as RoutingRow;
}

describe("RoutingTable", () => {
  it("renders one row per surface with a NO MODEL chip when unset", () => {
    const row = pinnedRow({ setting: { kind: "no-model" } as never });
    const { getByText } = render(
      React.createElement(RoutingTable, {
        rows: [row], liveModels, onPin: () => {}, onApplyRecommendation: () => {}, pending: false,
      }),
    );
    expect(getByText("NO MODEL")).toBeDefined();
  });

  it("formats cost under 1 cent with 4 decimals, at/above with 3", () => {
    const { getByText } = render(
      React.createElement(RoutingTable, {
        rows: [pinnedRow({ costPerTaskUsd7d: 0.004 })],
        liveModels, onPin: () => {}, onApplyRecommendation: () => {}, pending: false,
      }),
    );
    expect(getByText("$0.0040")).toBeDefined();
  });

  it("formats null cost/latency/eval as '-'", () => {
    const { getAllByText } = render(
      React.createElement(RoutingTable, {
        rows: [pinnedRow({ costPerTaskUsd7d: null, latencyP50Ms7d: null, evalScore: null })],
        liveModels, onPin: () => {}, onApplyRecommendation: () => {}, pending: false,
      }),
    );
    expect(getAllByText("-").length).toBeGreaterThanOrEqual(3);
  });

  it("formats latency in seconds at/above 1000ms", () => {
    const { getByText } = render(
      React.createElement(RoutingTable, {
        rows: [pinnedRow({ latencyP50Ms7d: 1500 })],
        liveModels, onPin: () => {}, onApplyRecommendation: () => {}, pending: false,
      }),
    );
    expect(getByText("1.5s")).toBeDefined();
  });

  it("shows Apply button only after the select value diverges from the committed model", () => {
    const { container, queryByText } = render(
      React.createElement(RoutingTable, {
        rows: [pinnedRow()], liveModels, onPin: () => {}, onApplyRecommendation: () => {}, pending: false,
      }),
    );
    expect(queryByText("Apply")).toBeNull(); // not dirty yet
    const select = container.querySelector("select") as HTMLSelectElement;
    fireEvent.change(select, { target: { value: "" } }); // switch to Auto
    expect(queryByText("Apply")).not.toBeNull();
  });

  it("calls onPin with null when Auto is applied", () => {
    let pinned: [string, string | null] | null = null;
    const { container, getByText } = render(
      React.createElement(RoutingTable, {
        rows: [pinnedRow()], liveModels,
        onPin: (surface, modelId) => { pinned = [surface, modelId]; },
        onApplyRecommendation: () => {}, pending: false,
      }),
    );
    const select = container.querySelector("select") as HTMLSelectElement;
    fireEvent.change(select, { target: { value: "" } });
    fireEvent.click(getByText("Apply"));
    expect(pinned).toEqual(["chat", null]);
  });

  it("disables the select and Apply button while pending", () => {
    const { container } = render(
      React.createElement(RoutingTable, {
        rows: [pinnedRow()], liveModels, onPin: () => {}, onApplyRecommendation: () => {}, pending: true,
      }),
    );
    expect((container.querySelector("select") as HTMLSelectElement).disabled).toBe(true);
  });

  it("shows a recommendation Apply action and calls onApplyRecommendation with its modelId", () => {
    let applied: [string, string] | null = null;
    const row = pinnedRow({ recommendation: { modelId: "m1" } as never });
    const { getByText } = render(
      React.createElement(RoutingTable, {
        rows: [row], liveModels, onPin: () => {},
        onApplyRecommendation: (surface, modelId) => { applied = [surface, modelId]; },
        pending: false,
      }),
    );
    fireEvent.click(getByText("Apply", { selector: "button" }));
    expect(applied).toEqual(["chat", "m1"]);
  });

  it("shows the recommendation reason (e.g. 'no eval data yet') when no recommendation exists", () => {
    const { getByText } = render(
      React.createElement(RoutingTable, {
        rows: [pinnedRow({ recommendation: null, recommendationReason: "no eval data yet" })],
        liveModels, onPin: () => {}, onApplyRecommendation: () => {}, pending: false,
      }),
    );
    expect(getByText("no eval data yet")).toBeDefined();
  });

  it("renders an empty tbody for a zero-row list without crashing", () => {
    const { container } = render(
      React.createElement(RoutingTable, {
        rows: [], liveModels, onPin: () => {}, onApplyRecommendation: () => {}, pending: false,
      }),
    );
    expect(container.querySelectorAll("tbody tr").length).toBe(0);
  });
});
```

Lines 908–1033 contain 10 `it()` blocks whose bodies are **entirely commented out** — `render()` is never called, so these tests pass trivially without asserting anything. This is worse than "untested": it reads as covered in a file listing but is a no-op. The `import { render, screen }` line at the top of the file is also commented out.

