import { describe, it, expect } from "bun:test";
import { render, fireEvent } from "@testing-library/react";
import React from "react";
import { ModeToggle } from "../ModeToggle";

describe("ModeToggle", () => {
  it("marks the active mode with aria-checked and shows its hint text", () => {
    const { getAllByRole, getByText } = render(
      React.createElement(ModeToggle, { mode: "plan", onChange: () => {} }),
    );
    const radios = getAllByRole("radio");
    expect(radios.find((r) => r.textContent?.includes("Plan"))?.getAttribute("aria-checked")).toBe("true");
    expect(radios.find((r) => r.textContent?.includes("Build"))?.getAttribute("aria-checked")).toBe("false");
    expect(getByText("thinking only, nothing changes")).toBeDefined();
  });

  it("calls onChange with 'build' when the Build option is clicked", () => {
    let next: string | null = null;
    const { getAllByRole } = render(
      React.createElement(ModeToggle, { mode: "plan", onChange: (m) => { next = m; } }),
    );
    fireEvent.click(getAllByRole("radio").find((r) => r.textContent?.includes("Build"))!);
    expect(next).toBe("build");
  });

  it("shows the live-agent dot only on the selected Build option", () => {
    const { container } = render(
      React.createElement(ModeToggle, { mode: "build", onChange: () => {} }),
    );
    expect(container.querySelectorAll(".rounded-full").length).toBe(1);
  });

  it("falls back to the first mode (plan) for an invalid/unrecognized mode value", () => {
    const { getAllByRole } = render(
      React.createElement(ModeToggle, { mode: "unknown" as never, onChange: () => {} }),
    );
    const radios = getAllByRole("radio");
    expect(radios.find((r) => r.textContent?.includes("Plan"))?.getAttribute("aria-checked")).toBe("true");
  });
});
