function mk(over: Partial<ApprovalItem> = {}): ApprovalItem {
  return {
    id: "a1", kind: "PROPOSAL", title: "Ship the checkout fix",
    evidence: ["12 signals point at checkout friction"],
    approveConsequence: "agent proceeds", rejectConsequence: "nothing runs",
    ...over,
