describe("ApprovalCard", () => {
  it("calls onApprove with the item id on approve click", () => {
    let approved: string | null = null;
    const { getByText } = render(
      React.createElement(ApprovalCard, { item: mk(), onApprove: (id) => { approved = id; }, onReject: () => {} }),
    );
    fireEvent.click(getByText("Approve"));
    expect(approved).toBe("a1");
  });

  it("disables both buttons while an action is pending (async onApprove)", async () => {
    let resolve!: () => void;
    const pendingPromise = new Promise<void>((r) => { resolve = r; });
    const { getByText } = render(
      React.createElement(ApprovalCard, { item: mk(), onApprove: () => pendingPromise, onReject: () => {} }),
    );
    fireEvent.click(getByText("Approve"));
    expect((getByText("Approving") as HTMLButtonElement).disabled).toBe(true);
    resolve();
    await waitFor(() => expect(getByText("Approve")).toBeDefined());
  });

  it("ignores a second click while the first action is still pending (no double-submit)", () => {
    let calls = 0;
    const never = new Promise<void>(() => {});
    const { getByText } = render(
      React.createElement(ApprovalCard, { item: mk(), onApprove: () => { calls++; return never; }, onReject: () => {} }),
    );
    fireEvent.click(getByText("Approve"));
    fireEvent.click(getByText("Approving"));
    expect(calls).toBe(1);
  });

  it("reject click while approve is pending is a no-op (single pending lock covers both actions)", () => {
    let rejectCalls = 0;
    const never = new Promise<void>(() => {});
    const { getByText } = render(
      React.createElement(ApprovalCard, { item: mk(), onApprove: () => never, onReject: () => { rejectCalls++; } }),
    );
    fireEvent.click(getByText("Approve"));
    fireEvent.click(getByText("Reject"));
    expect(rejectCalls).toBe(0);
  });

  it("renders onOpen as a clickable title only when onOpen is provided", () => {
    const { container, rerender } = render(
      React.createElement(ApprovalCard, { item: mk(), onApprove: () => {}, onReject: () => {} }),
    );
    expect(container.querySelector("h3 button")).toBeNull();
    rerender(React.createElement(ApprovalCard, { item: mk(), onApprove: () => {}, onReject: () => {}, onOpen: () => {} }));
    expect(container.querySelector("h3 button")).not.toBeNull();
  });

  it("formats a future or malformed timestamp without throwing (shortTime is not exported, so drive it through render)", () => {
    const { container } = render(
      React.createElement(ApprovalCard, { item: mk({ timestamp: "not-a-date" }), onApprove: () => {}, onReject: () => {} }),
    );
    expect(container.querySelector("time")?.textContent).toBe("not-a-date"); // NaN-guard fallback
  });

  it("omits the evidence list entirely when evidence is empty", () => {
    const { container } = render(
      React.createElement(ApprovalCard, { item: mk({ evidence: [] }), onApprove: () => {}, onReject: () => {} }),
    );
    expect(container.querySelector("ul")).toBeNull();
  });
});

